import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"節","description":"周易正义 - 節","frontmatter":{"title":"節","description":"周易正义 - 節"},"headers":[],"relativePath":"zh/classics/zhengyi/060.md","filePath":"zh/classics/zhengyi/060.md"}'),l={name:"zh/classics/zhengyi/060.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>水泽节</p></blockquote><blockquote><p>卦辞：亨。苦节，不可贞。</p></blockquote><blockquote><p>彖曰：节亨。刚柔分而刚得中。苦节不可贞，其道穷也。说以行险，当位以节，中正以通。天地节而四时成。节以制度，不伤财，不害民。</p></blockquote><h1 id="節" tabindex="-1">節 <a class="header-anchor" href="#節" aria-label="Permalink to “節”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“节”，卦名也。《彖》曰：“节以制度。”《杂卦》云：“节，止也。”然则节者制度之名。节，止之义，制事有节，其道乃亨，故曰“节，亨”。节须得中，为节过苦，伤於刻薄，物所不堪，不可复正，故曰“苦节不可贞”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="节-亨-刚柔分而刚得中。-​" tabindex="-1">“节，亨”，刚柔分而刚得中。 ​ <a class="header-anchor" href="#节-亨-刚柔分而刚得中。-​" aria-label="Permalink to ““节，亨”，刚柔分而刚得中。 ​”">​</a></h3><p>王弼：坎阳而兑阴也。阳上而阴下，刚柔分也。刚柔分而不乱，刚得中而为制主，节之义也。节之大者，莫若刚柔分，男女别也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就上下二体居二、五刚中，释所以为节得亨之义也。坎刚居上，兑柔处下，是刚柔分也。刚柔分，男女别，节之大义也。二、五以刚居中，为制之主，所以得节，节不违中，所以得亨，故曰“节，亨，刚柔分而刚得中”也。</p><h3 id="苦节不可贞-其道穷也。-​" tabindex="-1">“苦节不可贞”，其道穷也。 ​ <a class="header-anchor" href="#苦节不可贞-其道穷也。-​" aria-label="Permalink to ““苦节不可贞”，其道穷也。 ​”">​</a></h3><p>王弼：为节过苦，则物所不能堪也。物不能堪，则不可复正也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：为节过苦，不可为正。若以苦节为正，则其道困穷，故曰“苦节不可贞，其道穷”也。</p><h3 id="说以行险-当位以节-中正以通。-​" tabindex="-1">说以行险，当位以节，中正以通。 ​ <a class="header-anchor" href="#说以行险-当位以节-中正以通。-​" aria-label="Permalink to “说以行险，当位以节，中正以通。 ​”">​</a></h3><p>王弼：然后及亨也。无说而行险，过中而为节，则道穷也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：上言“苦节不可贞，其道穷”者，正由为节不中，则物所不说，不可复正，其道困穷，故更就二体及四、五当位，重释行节得亨之义，以明苦节之穷也。“行险以说”，则为节得中。“当位以节”，则可以为正。良由中而能正，所以得通，故曰：“中正以通”，此其所以为亨也。</p><h3 id="天地节而四时成-节以制度-不伤财-不害民。-​" tabindex="-1">天地节而四时成，节以制度，不伤财，不害民。 ​ <a class="header-anchor" href="#天地节而四时成-节以制度-不伤财-不害民。-​" aria-label="Permalink to “天地节而四时成，节以制度，不伤财，不害民。 ​”">​</a></h3><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“天地节而四时成”者，此下就天地与人广明节义。天地以气序为节，使寒暑往来，各以其序，则四时功成之也。王者以制度为节，使用之有道，役之有时，则不伤财，不害民也。</p><h2 id="《象》曰-泽上有水-节。君子以制数度-议德行。-​" tabindex="-1">《象》曰：泽上有水，节。君子以制数度，议德行。 ​ <a class="header-anchor" href="#《象》曰-泽上有水-节。君子以制数度-议德行。-​" aria-label="Permalink to “《象》曰：泽上有水，节。君子以制数度，议德行。 ​”">​</a></h2><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“泽上有水，节”者，水在泽中，乃得其节，故曰“泽上有水，节”也。“君子以制数度，议德行”者，数度，谓尊卑礼命之多少。德行，谓人才堪任之优劣。君子象节以制其礼数等差，皆使有度，议人之德行任用，皆使得宜。</p><h2 id="初九-不出户庭-无咎。-​" tabindex="-1">初九：不出户庭，无咎。 ​ <a class="header-anchor" href="#初九-不出户庭-无咎。-​" aria-label="Permalink to “初九：不出户庭，无咎。 ​”">​</a></h2><p>王弼：为节之初，将整离散而立制度者也，故明於通塞，虑於险为，不出户庭，慎密不失，然后事济而无咎也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>“初九”至“无咎”。○正义曰：初九处节之初，将立制度，宜其慎密，不出户庭，若不慎而泄，则民情奸险，应之以伪，故慎密不失，然后事济而无咎，故曰“不出户庭，无咎”。○注“将整离散而立制度者也”。○正义曰：《序卦》云：“物不可以终离，故受之以节。”此卦承《涣》之后，初九居节之初，故曰“将整离散而立法度”也。</p><h3 id="《象》曰-不出户庭-知通塞也。-​" tabindex="-1">《象》曰：“不出户庭”，知通塞也。 ​ <a class="header-anchor" href="#《象》曰-不出户庭-知通塞也。-​" aria-label="Permalink to “《象》曰：“不出户庭”，知通塞也。 ​”">​</a></h3><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“知通塞”者，识时通塞，所以不出也。</p><h2 id="九二-不出门庭-凶。-​" tabindex="-1">九二：不出门庭，凶。 ​ <a class="header-anchor" href="#九二-不出门庭-凶。-​" aria-label="Permalink to “九二：不出门庭，凶。 ​”">​</a></h2><p>王弼：初已造之，至二宜宣其制矣，而故匿之，失时之极，则遂废矣。故不出门庭，则凶也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：初巳制法，至二宜宣。若犹匿之，则失时之极，可施之事，则遂废矣。不出门庭，所以致凶，故曰“不出门庭，凶”。</p><h3 id="《象》曰-不出门庭-凶-失时极也。-​" tabindex="-1">《象》曰：“不出门庭，凶”，失时极也。 ​ <a class="header-anchor" href="#《象》曰-不出门庭-凶-失时极也。-​" aria-label="Permalink to “《象》曰：“不出门庭，凶”，失时极也。 ​”">​</a></h3><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“失时极”者，极，中也。应出不出，失时之中，所以为凶。</p><h2 id="六三-不节若-则嗟若-无咎。-​" tabindex="-1">六三：不节若，则嗟若，无咎。 ​ <a class="header-anchor" href="#六三-不节若-则嗟若-无咎。-​" aria-label="Permalink to “六三：不节若，则嗟若，无咎。 ​”">​</a></h2><p>王弼：若，辞也。以阴处阳，以柔乘刚，违节之道，以至哀嗟。自巳所致，无所怨咎，故曰“无咎”也。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：节者，制度之卦，处节之时，位不可失，六三以阴处阳，以柔乘刚，失位骄逆，违节之道，祸将及己，以至哀嗟，故曰“不节苦，则嗟若”也。祸自已致，无所怨咎，故曰“无咎”。</p><h3 id="《象》曰-不节-之-嗟-又谁-咎-也。-​" tabindex="-1">《象》曰：“不节”之“嗟”，又谁“咎”也。 ​ <a class="header-anchor" href="#《象》曰-不节-之-嗟-又谁-咎-也。-​" aria-label="Permalink to “《象》曰：“不节”之“嗟”，又谁“咎”也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“又谁咎”者，由己不节，自致祸灾，又欲怨咎谁乎？</p><h2 id="六四-安节-亨。-​" tabindex="-1">六四：安节，亨。 ​ <a class="header-anchor" href="#六四-安节-亨。-​" aria-label="Permalink to “六四：安节，亨。 ​”">​</a></h2><p>王弼：得位而顺，不改其节，而能亨者也。承上以斯，得其道也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：六四得位，而上顺於五，是得节之道。但能安行此节而不改变，则何往不通，故曰“安节亨”，明六三以失位乘刚，则失节而招咎，六四以得位承阳，故安节而致亨。</p><h3 id="《象》曰-安节-之-亨-承上道也。-​" tabindex="-1">《象》曰：“安节”之“亨”，承上道也。 ​ <a class="header-anchor" href="#《象》曰-安节-之-亨-承上道也。-​" aria-label="Permalink to “《象》曰：“安节”之“亨”，承上道也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：承上道者，以能承於上，故不失其道也。</p><h2 id="九五-甘节-吉。往有尚。-​" tabindex="-1">九五：甘节，吉。往有尚。 ​ <a class="header-anchor" href="#九五-甘节-吉。往有尚。-​" aria-label="Permalink to “九五：甘节，吉。往有尚。 ​”">​</a></h2><p>王弼：当位居中，为节之主不失其中，不伤财，不害民之谓也。为节之不苦，非甘而何？术斯以往，往有尚也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“甘”者，不苦之名也。九五居於尊位，得正履中，能以中正为节之主，则当《彖》曰：“节以制度，不伤财，不害民”之谓也。为节而无伤害，则是不苦而甘，所以得吉，故曰“甘节，吉”。以此而行，所往皆有嘉尚，故曰“往有尚”也。</p><h3 id="象曰-甘节-之-吉-居位中也。-​" tabindex="-1">象曰：“甘节”之“吉”，居位中也。 ​ <a class="header-anchor" href="#象曰-甘节-之-吉-居位中也。-​" aria-label="Permalink to “象曰：“甘节”之“吉”，居位中也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“居位中”者，以居尊位而得中，故致甘节之吉也。</p><h2 id="上六-苦节-贞凶-悔亡。-​" tabindex="-1">上六：苦节，贞凶，悔亡。 ​ <a class="header-anchor" href="#上六-苦节-贞凶-悔亡。-​" aria-label="Permalink to “上六：苦节，贞凶，悔亡。 ​”">​</a></h2><p>王弼：过节之中，以致亢极，苦节者也。以斯施人，物所不堪，正之凶也。以斯脩身，行在无妄，故得悔亡。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：上六处节之极，过节之中，节不能甘，以至於苦，故曰“苦节”也。为节过苦，物所不堪，不可复正，正之凶也，故曰“贞凶”。若以苦节施人，则是正道之凶。若以苦节脩身，则俭约无妄，可得亡悔，故曰“悔亡”也。</p><h3 id="《象》曰-苦节-贞凶-其道穷也。-​" tabindex="-1">《象》曰：“苦节，贞凶”，其道穷也。 ​ <a class="header-anchor" href="#《象》曰-苦节-贞凶-其道穷也。-​" aria-label="Permalink to “《象》曰：“苦节，贞凶”，其道穷也。 ​”">​</a></h3>',65)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
